class BulkUploadsApi:
    """`bulk-uploads` endpoints."""

    def __init__(self, transport: "Transport") -> None:
        self._c = transport

    def upload_file(self, file: FileInput, format: str, kind: BulkUploadKind, *, create_missing_accounts: bool | None = None, layout_id: str | None = None) -> BulkUploadAccepted:
        """Upload File.

        POST /api/v1/bulk-uploads

        Uploads a file to import in the background. Poll `status_url` for progress. A file
        that can't be read at all comes back `rejected`, with the reason in `error`. An
        issued-check file in the customer's own columns or a fixed-width format is sent with
        `format=layout` and its `layout_id`.
        """
        return self._c.call("POST", "/api/v1/bulk-uploads", data={"create_missing_accounts": create_missing_accounts, "format": format, "kind": kind, "layout_id": layout_id}, files={"file": file})

    def list_import_formats(self) -> list[ImportFormatRead]:
        """List Import Formats.

        GET /api/v1/bulk-uploads/formats

        The import formats this organization can send to `POST /api/v1/bulk-uploads`: the
        built-in ones and any a plugin provides that an admin has turned on, limited to the
        kinds the caller may upload.
        """
        return self._c.call("GET", "/api/v1/bulk-uploads/formats")

    def list_import_layouts(self) -> list[ImportLayoutRead]:
        """List Import Layouts.

        GET /api/v1/bulk-uploads/layouts

        The issued-check file layouts the caller can upload with (Settings → Issue-file
        layouts): a customer's own and the bank's. Send one's `id` as `layout_id` with
        `kind=issued_items` and `format=layout`.
        """
        return self._c.call("GET", "/api/v1/bulk-uploads/layouts")

    def get_bulk_upload(self, upload_id: str) -> BulkUploadRead:
        """Get Bulk Upload.

        GET /api/v1/bulk-uploads/{upload_id}

        Where the import is: `queued`, `processing` (`processed_rows` of `total_rows`),
        `completed`, `rejected` (nothing imported; see `error`) or `failed`.
        """
        return self._c.call("GET", f"/api/v1/bulk-uploads/{_path(upload_id)}")

    def get_bulk_upload_results(self, upload_id: str, *, failures_only: bool | None = None, limit: int | None = None, offset: int | None = None) -> list[BulkUploadRowRead]:
        """Get Bulk Upload Results.

        GET /api/v1/bulk-uploads/{upload_id}/results

        Each imported row's outcome, in file order, paged. `index` is the row's position in
        the request (0-based) or file.
        """
        return self._c.call("GET", f"/api/v1/bulk-uploads/{_path(upload_id)}/results", query={"failures_only": failures_only, "limit": limit, "offset": offset})

    def iter_get_bulk_upload_results(self, upload_id: str, *, failures_only: bool | None = None, limit: int | None = None) -> Iterator[BulkUploadRowRead]:
        """Every row of get_bulk_upload_results, following each page's `Link: rel="next"`.

        GET /api/v1/bulk-uploads/{upload_id}/results
        """
        return self._c.paginate("GET", f"/api/v1/bulk-uploads/{_path(upload_id)}/results", query={"failures_only": failures_only, "limit": limit})


